// `conventions/`, `gotchas/` and `people/`, seeded by the audit (KT-819 DoD 11)
// from what the team stated in the briefing and from the documents it already
// had: deterministic, no agent, nothing invented. A file Kronn generated carries
// the briefing marker and is regenerated by each audit; a person takes one over
// by deleting that line.

use std::path::Path;

use serde::Serialize;

use super::{
    branch_label, cadence_label, cell, commit_label, merge_label, review_label, role_label,
    yes_no_label, GENERATED_MARKER, NOT_PROVIDED,
};
use crate::models::SavedBriefing;

const GENERATED_NOTE: &str = " — regenerated by each audit from the briefing; edit the briefing, or delete this line to own the file. -->";
/// What the README said before the audit seeded these folders.
const OLD_README_MARK: &str = "**Empty by design after the initial audit.**";
/// The files this module owns, so one the briefing no longer feeds goes away.
const SEEDED: [&str; 3] = [
    "gotchas/known-traps.md",
    "people/team.md",
    "conventions/git-workflow.md",
];
const FOLDERS: [&str; 3] = ["conventions", "gotchas", "people"];
const MAX_POINTERS: usize = 10;

#[derive(Debug, Default, Clone, PartialEq, Eq, Serialize)]
pub(crate) struct SeedReport {
    /// Paths under the docs folder that were created or regenerated.
    pub written: Vec<String>,
    /// Generated files the briefing no longer feeds.
    pub removed: Vec<String>,
    /// Files a person took over (the marker is gone): left as they are.
    pub kept_human_owned: Vec<String>,
    pub errors: Vec<String>,
}

struct Entry {
    folder: &'static str,
    label: String,
    /// Link target relative to the folder's README.
    target: String,
    hint: &'static str,
}

fn generated(body: &str) -> String {
    format!("{GENERATED_MARKER}{GENERATED_NOTE}\n{body}")
}

fn is_generated(content: &str) -> bool {
    content.trim_start().starts_with(GENERATED_MARKER)
}

/// A free-text answer as a quotation a parser cannot read as structure: no
/// heading, comment or placeholder survives.
fn quoted(text: &str) -> String {
    text.replace("{{", "{ {")
        .replace("}}", "} }")
        .replace("<!--", "< !--")
        .replace("-->", "-- >")
        .lines()
        .map(|line| format!("> {}", line.trim_end()))
        .collect::<Vec<_>>()
        .join("\n")
}

fn is_nothing(answer: &str) -> bool {
    let a = answer.trim().trim_end_matches('.').to_ascii_lowercase();
    a.is_empty() || matches!(a.as_str(), "none" | "n/a" | "na" | "-" | "nothing")
}

/// `[label](target)` when the file exists, else the plain label.
fn link_if_exists(docs_dir: &Path, rel: &str, label: &str, target: &str) -> String {
    if docs_dir.join(rel).is_file() {
        format!("[{label}]({target})")
    } else {
        label.to_string()
    }
}

fn traps_file(saved: &SavedBriefing, docs_dir: &Path) -> Option<(String, String)> {
    if is_nothing(&saved.traps) {
        return None;
    }
    let source = link_if_exists(
        docs_dir,
        "briefing.md",
        "Traps & Fragile Areas",
        "../briefing.md",
    );
    Some((
        "gotchas/known-traps.md".into(),
        format!(
            "# Known traps\n\nThe team listed these in the briefing ({source}). Kronn did not verify them: \
check a trap against the code before relying on it, and give a confirmed one its own file in this folder.\n\n{}\n",
            quoted(saved.traps.trim())
        ),
    ))
}

fn team_file(saved: &SavedBriefing, docs_dir: &Path) -> Option<(String, String)> {
    let people = saved
        .project
        .as_ref()
        .map(|p| p.people.as_slice())
        .unwrap_or_default();
    let team = (!is_nothing(&saved.team)).then(|| saved.team.trim());
    if people.is_empty() && team.is_none() {
        return None;
    }
    let source = link_if_exists(docs_dir, "briefing.md", "Team", "../briefing.md");
    let mut body = format!(
        "# Team\n\nAs entered in the briefing ({source}); nothing else about anyone is recorded here.\n"
    );
    if !people.is_empty() {
        body.push_str("\n| Role | Name | Contact |\n|------|------|---------|\n");
        for person in people {
            let value = |v: &str| {
                if v.is_empty() {
                    NOT_PROVIDED.to_string()
                } else {
                    cell(v)
                }
            };
            body.push_str(&format!(
                "| {} | {} | {} |\n",
                role_label(person.role),
                value(&person.name),
                value(&person.contact)
            ));
        }
    }
    if let Some(team) = team {
        body.push_str(&format!("\n## In the team's words\n\n{}\n", quoted(team)));
    }
    Some(("people/team.md".into(), body))
}

fn workflow_file(saved: &SavedBriefing, docs_dir: &Path) -> Option<(String, String)> {
    let project = saved.project.as_ref()?;
    let mut rows: Vec<(&str, String)> = Vec::new();
    if let Some(branch) = branch_label(project.default_branch) {
        rows.push(("Default branch", format!("`{branch}`")));
    }
    for (topic, value) in [
        ("Commit convention", commit_label(project.commit_convention)),
        (
            "Sign-off (`Signed-off-by`)",
            yes_no_label(project.signoff_required),
        ),
        ("Merge strategy", merge_label(project.merge_strategy)),
        ("Review", review_label(project.review_policy)),
        ("Release cadence", cadence_label(project.release_cadence)),
    ] {
        if value != NOT_PROVIDED {
            rows.push((topic, value.to_string()));
        }
    }
    if rows.is_empty() {
        return None;
    }
    let source = link_if_exists(docs_dir, "briefing.md", "Project facts", "../briefing.md");
    let page = link_if_exists(docs_dir, "project.md", "project", "../project.md");
    let mut body = format!(
        "# Git workflow\n\nThe team's answers in the briefing ({source}); the whole page is {page}.\n\n\
| Topic | Convention |\n|-------|------------|\n"
    );
    for (topic, value) in rows {
        body.push_str(&format!("| {topic} | {value} |\n"));
    }
    Some(("conventions/git-workflow.md".into(), body))
}

/// Existing documents moved to `legacy/` that read as conventions, gotchas or
/// people: listed with a link, never copied.
fn legacy_pointers(docs_dir: &Path) -> Vec<Entry> {
    const KEYWORDS: [(&str, &[&str]); 3] = [
        (
            "conventions",
            &[
                "contributing",
                "convention",
                "style",
                "guideline",
                "standard",
                "naming",
            ],
        ),
        (
            "gotchas",
            &[
                "gotcha",
                "pitfall",
                "troubleshoot",
                "faq",
                "known-issue",
                "known_issue",
                "caveat",
                "trap",
            ],
        ),
        (
            "people",
            &[
                "owners",
                "maintainers",
                "team",
                "codeowners",
                "people",
                "contacts",
            ],
        ),
    ];
    let legacy = docs_dir.join("legacy");
    if !legacy.is_dir() {
        return Vec::new();
    }
    let mut out: Vec<Entry> = Vec::new();
    for entry in walkdir::WalkDir::new(&legacy)
        .max_depth(3)
        .sort_by_file_name()
        .into_iter()
        .filter_map(|e| e.ok())
        .filter(|e| e.file_type().is_file())
    {
        let Ok(rel) = entry.path().strip_prefix(&legacy) else {
            continue;
        };
        let rel = rel.to_string_lossy().replace('\\', "/");
        let safe = rel
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || matches!(c, '.' | '_' | '-' | '/'));
        if !safe || !rel.to_ascii_lowercase().ends_with(".md") {
            continue;
        }
        let stem = entry
            .path()
            .file_stem()
            .map(|s| s.to_string_lossy().to_ascii_lowercase())
            .unwrap_or_default();
        let Some((folder, _)) = KEYWORDS
            .iter()
            .find(|(_, words)| words.iter().any(|w| stem.contains(w)))
        else {
            continue;
        };
        if out.iter().filter(|e| e.folder == *folder).count() >= MAX_POINTERS {
            continue;
        }
        out.push(Entry {
            folder,
            label: format!("legacy/{rel}"),
            target: format!("../legacy/{rel}"),
            hint: "an existing document, kept as written",
        });
    }
    out
}

enum Outcome {
    Written,
    Unchanged,
    KeptHumanOwned,
}

/// Write `body` at `target` when Kronn owns what is there: nothing, a file
/// carrying the generated marker, or (README) its untouched scaffold.
fn write_owned(
    project_root: &Path,
    target: &Path,
    body: &str,
    scaffold: Option<&str>,
) -> Result<Outcome, String> {
    crate::core::fs_guard::assert_contained_no_symlink(project_root, target)?;
    match std::fs::read_to_string(target) {
        Ok(existing) => {
            let owned = is_generated(&existing)
                || scaffold.is_some_and(|s| {
                    existing.trim() == s.trim() || existing.contains(OLD_README_MARK)
                });
            if !owned {
                return Ok(Outcome::KeptHumanOwned);
            }
            if existing == body {
                return Ok(Outcome::Unchanged);
            }
        }
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {}
        Err(e) => return Err(format!("read {}: {e}", target.display())),
    }
    if let Some(parent) = target.parent() {
        crate::core::fs_guard::guarded_create_dir_all(project_root, parent)?;
    }
    crate::core::mcp_scanner::atomic_write(target, body)?;
    Ok(Outcome::Written)
}

fn scaffold_of(folder: &str) -> &'static str {
    crate::api::projects::SUBFOLDER_READMES
        .iter()
        .find(|(name, _)| *name == folder)
        .map(|(_, text)| *text)
        .unwrap_or("")
}

/// Seed the three folders under `docs_dir` from the briefing `notes`.
pub(crate) fn seed(project_root: &Path, docs_dir: &Path, notes: Option<&str>) -> SeedReport {
    let mut report = SeedReport::default();
    let saved = notes.map(super::super::briefing_load::parse_saved_briefing);
    let mut files: Vec<(String, String)> = Vec::new();
    if let Some(saved) = &saved {
        files.extend(traps_file(saved, docs_dir));
        files.extend(team_file(saved, docs_dir));
        files.extend(workflow_file(saved, docs_dir));
    }

    let mut entries: Vec<Entry> = Vec::new();
    for (rel, body) in &files {
        let (folder, name) = rel.split_once('/').unwrap_or(("", rel));
        let Some(folder) = FOLDERS.iter().find(|f| **f == folder) else {
            continue;
        };
        let target = docs_dir.join(rel);
        match write_owned(project_root, &target, &generated(body), None) {
            Ok(Outcome::Written) => report.written.push(rel.clone()),
            Ok(Outcome::Unchanged) => {}
            Ok(Outcome::KeptHumanOwned) => report.kept_human_owned.push(rel.clone()),
            Err(e) => {
                report.errors.push(format!("{rel}: {e}"));
                continue;
            }
        }
        entries.push(Entry {
            folder,
            label: name.trim_end_matches(".md").to_string(),
            target: name.to_string(),
            hint: "from the briefing",
        });
    }

    // A generated file the briefing no longer feeds goes away; a file a person
    // took over (no marker) never does.
    for rel in SEEDED {
        if files.iter().any(|(kept, _)| kept == rel) {
            continue;
        }
        let target = docs_dir.join(rel);
        let Ok(existing) = std::fs::read_to_string(&target) else {
            continue;
        };
        if !is_generated(&existing) {
            continue;
        }
        let removed = crate::core::fs_guard::assert_contained_no_symlink(project_root, &target)
            .and_then(|_| std::fs::remove_file(&target).map_err(|e| e.to_string()));
        match removed {
            Ok(()) => report.removed.push(rel.to_string()),
            Err(e) => report.errors.push(format!("{rel}: {e}")),
        }
    }

    entries.extend(legacy_pointers(docs_dir));
    for folder in FOLDERS {
        let scaffold = scaffold_of(folder);
        let mine: Vec<&Entry> = entries.iter().filter(|e| e.folder == folder).collect();
        let target = docs_dir.join(folder).join("README.md");
        if !docs_dir.join(folder).is_dir() {
            continue;
        }
        let body = if mine.is_empty() {
            scaffold.to_string()
        } else {
            let mut body = generated(scaffold);
            body.push_str("\n## Seeded by the audit\n\n");
            for entry in mine {
                body.push_str(&format!(
                    "- [{}]({}) — {}\n",
                    entry.label, entry.target, entry.hint
                ));
            }
            body
        };
        let rel = format!("{folder}/README.md");
        match write_owned(project_root, &target, &body, Some(scaffold)) {
            Ok(Outcome::Written) => report.written.push(rel),
            Ok(Outcome::Unchanged) | Ok(Outcome::KeptHumanOwned) => {}
            Err(e) => report.errors.push(format!("{rel}: {e}")),
        }
    }
    report
}

